// 递归生成所有可能的路径
void dfs(int n, vector<vector<int>> &distance, vector<int> &currentPath, vector<vector<int>> & paths, vector<bool> &visited) {
    if (currentPath.size() == n -1) {
        paths.push_back(vector<int>(currentPath.begin(), currentPath.end()));
        return;
    }
    for (int i = 1; i < n; i++) {
        if (!visited[i]) {
            currentPath.push_back(i);
            visited[i] = true;
​
            dfs(n, distance, currentPath, paths, visited);
            // 递归回溯
            visited[i] = false;
            currentPath.pop_back();
        }
    }
}
