int getMinPath(int n, vector<vector<int>> distance) {
    vector<bool> visited(n, false);
    vector<vector<int>> paths;
    vector<int> currentPath;
    dfs(n, distance, currentPath, paths, visited);
    int res = INT_MAX;
    // 求出所有路径中的最小值
    for (int i = 0; i < paths.size(); i++) {
        vector<int> path = paths[i];
        int tmp = distance[0][path[0]];
        for (int j = 0; j < path.size() -1; j++) {
            tmp += distance[path[j]][path[j+1]];
        }
        // 返回1号站
        tmp += distance[path[path.size()-1]][0];
        res = min(res, tmp);
    }
    return res;
}
