// 计算最短路径
function getMinPath(n, distance) {
    let res = Infinity;

    // 生成所有可能的路径 (从 1 开始的排列)
    function permute(arr, l, r) {
        if (l === r) {
            let tmp = distance[0][arr[0]];
            for (let i = 0; i < arr.length - 1; i++) {
                tmp += distance[arr[i]][arr[i + 1]];
            }
            // 返回起点
            tmp += distance[arr[arr.length - 1]][0];
            res = Math.min(res, tmp);
            return;
        }
        for (let i = l; i <= r; i++) {
            [arr[l], arr[i]] = [arr[i], arr[l]];
            permute(arr, l + 1, r);
            [arr[l], arr[i]] = [arr[i], arr[l]];
        }
    }
​
    let nodes = Array.from({ length: n - 1 }, (_, i) => i + 1);
    permute(nodes, 0, nodes.length - 1);
​
    return res;
}
