package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 计算最短路径
func getMinPath(n int, distance [][]int) int {
    res := int(1e9) // 设置最大值
​
    // 生成所有可能的路径 (从 1 开始的排列)
    nodes := make([]int, n-1)
    for i := 1; i < n; i++ {
        nodes[i-1] = i
    }
​
    var permute func([]int, int)
    permute = func(arr []int, l int) {
        if l == len(arr) {
            tmp := distance[0][arr[0]]
            for i := 0; i < len(arr)-1; i++ {
                tmp += distance[arr[i]][arr[i+1]]
            }
            // 返回起点
            tmp += distance[arr[len(arr)-1]][0]
            if tmp < res {
                res = tmp
            }
            return
        }
        for i := l; i < len(arr); i++ {
            arr[l], arr[i] = arr[i], arr[l]
            permute(arr, l+1)
            arr[l], arr[i] = arr[i], arr[l]
        }
    }
​
    permute(nodes, 0)
    return res
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    distance := make([][]int, n)
    for i := 0; i < n; i++ {
        scanner.Scan()
        line := strings.Fields(scanner.Text())
        distance[i] = make([]int, n)
        for j := 0; j < n; j++ {
            distance[i][j], _ = strconv.Atoi(line[j])
        }
    }
​
    res := getMinPath(n, distance)
    fmt.Println(res)
}
